$err = $false; foreach ($f in @('install.ps1', '.agentic/scripts/verify.ps1', '.agentic/scripts/validate-task.ps1', '.agentic/scripts/validate-context.ps1', '.agentic/scripts/validate-skills.ps1', '.agentic/scripts/validate-handoff.ps1', '.agentic/orchestration/coordinator.ps1')) { try { [scriptblock]::Create((Get-Content -Raw -LiteralPath $f)) | Out-Null } catch { Write-Error $_.Exception.Message; $err = $true } }; if ($err) { exit 1 }